import { rollbackCheckout } from "../../src/checkout/rollback";
import { dummyOrder, failingTransaction } from "../fixtures";

test("rollback releases reservations inside the checkout transaction", async () => {
  const order = dummyOrder({ reservations: 3 });
  const tx = failingTransaction({ failAfter: 2 });
  await expect(rollbackCheckout(order, tx)).rejects.toThrow();
  expect(tx.committed).toBe(false);
  expect(tx.released).toEqual([]);
});
